import React, { createContext, useContext, useState, useRef, useEffect, useCallback } from 'react'

const AEPSContext = createContext()

const initialCommonFormData = {
  bank: null,
  bank_id: "",
  aadharNumber: "",
  mobile: "",
  amount: "",
  selectedDeviceId: null,
};

const getStoredCache = () => {
  try {
    const raw = sessionStorage.getItem("aeps_common_cache");
    if (raw) {
      return JSON.parse(raw);
    }
  } catch (e) {}
  return null;
};

const AEPSContextProvider = ({ walletCall, children }) => {
  const [allAEPSProvider, setAllAEPSProvider] = useState([]);
  const [selectedAEPSProvider, setSelectedAEPSProvider] = useState();
  const [aepsglobalLoader, setAepsGlobalLoader] = useState(false);

  const [aepscurrentPage, setAepsCurrentPage] = useState('');
  const [dailyAuth, setDailyAuth] = useState(false);
  const [onBoardingAuth, setOnBoardingAuth] = useState(false);
  const [triggerAuthApi, setTriggerAuthApi] = useState(false);

  // In-memory cache for common fields across AEPS tabs
  const initialCache = getStoredCache() || initialCommonFormData;
  const aepsFormCacheRef = useRef({ ...initialCache });
  const [commonFormData, setCommonFormData] = useState({ ...initialCache });

  const updateCommonFormData = useCallback((fields) => {
    if (!fields) return;
    aepsFormCacheRef.current = {
      ...aepsFormCacheRef.current,
      ...fields,
    };
    try {
      sessionStorage.setItem("aeps_common_cache", JSON.stringify(aepsFormCacheRef.current));
    } catch (e) {}
  }, []);

  const getCommonFormData = useCallback(() => {
    return aepsFormCacheRef.current;
  }, []);

  const clearCommonFormData = useCallback(() => {
    aepsFormCacheRef.current = { ...initialCommonFormData };
    setCommonFormData({ ...initialCommonFormData });
    try {
      sessionStorage.removeItem("aeps_common_cache");
    } catch (e) {}
  }, []);

  // When user navigates away from this AEPS section (component unmounts),
  // clear cache so it does not persist forever.
  useEffect(() => {
    return () => {
      try {
        sessionStorage.removeItem("aeps_common_cache");
      } catch (e) {}
    };
  }, []);

  return (
    <AEPSContext.Provider
      value={{
        setTriggerAuthApi,
        triggerAuthApi,
        walletCall,
        setDailyAuth,
        setOnBoardingAuth,
        setSelectedAEPSProvider,
        allAEPSProvider,
        setAllAEPSProvider,
        selectedAEPSProvider,
        aepsglobalLoader,
        setAepsGlobalLoader,
        aepscurrentPage,
        setAepsCurrentPage,
        commonFormData,
        updateCommonFormData,
        getCommonFormData,
        clearCommonFormData,
      }}
    >
      {children}
    </AEPSContext.Provider>
  );
};

export const useAEPSService = () => useContext(AEPSContext);

export default AEPSContextProvider;